import{c as t,Q as r,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Multi-operator setup","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/multi-operator-setup.md","filePath":"user/reference/multi-operator-setup.md"}'),a={name:"user/reference/multi-operator-setup.md"};function s(i,e,h,d,l,c){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="multi-operator-setup" tabindex="-1">Multi-operator setup <a class="header-anchor" href="#multi-operator-setup" aria-label="Permalink to &quot;Multi-operator setup&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up the network and the volunteers&#39; laptops, tablets and screens at the venue.</p><p>How to run one event from several devices at once: the network, the server computer, what each device needs, and what to expect when two people work on the same thing or a device drops off the network. For <em>why</em> Manager works this way, see <a href="./../what-is-mesho-manager/">How meshO Manager works</a>.</p><h2 id="the-shape-of-it" tabindex="-1">The shape of it <a class="header-anchor" href="#the-shape-of-it" aria-label="Permalink to &quot;The shape of it&quot;">​</a></h2><p>One computer runs Manager: the <strong>server</strong>. Every other device opens it in a web browser, over the venue&#39;s local network. Nothing is installed on them, and they all see the same event, live.</p><ul><li><strong>Everything is kept on the server.</strong> A card read at a download laptop is stored on the server the moment it&#39;s read, not on the laptop.</li><li><strong>Every change reaches every device</strong> within a second or so, with no refreshing.</li><li><strong>meshO Prime plugs into the server</strong>, over USB. A SportIdent reader or a USB printer plugs into whichever device uses it.</li></ul><h2 id="the-network" tabindex="-1">The network <a class="header-anchor" href="#the-network" aria-label="Permalink to &quot;The network&quot;">​</a></h2><p>You need one local network that the server and every device join. It doesn&#39;t need the internet.</p><ul><li><strong>A Wi-Fi router, or a router with a switch.</strong> A small travel router is plenty for most events. Put the <strong>server on a cable</strong> to the router if you can: it&#39;s the one device everything depends on.</li><li><strong>Laptops at fixed desks</strong> (download, registration) are better on a cable too, if the router has the ports. Phones, tablets and TVs can use Wi-Fi.</li><li><strong>Keep the server&#39;s address from changing.</strong> Add a <strong>DHCP reservation</strong> for the server on the router, so it gets the same IP every time, and the links you hand out keep working. See <a href="./server-addresses#when-the-ip-changes">When the IP changes</a>.</li></ul><h3 id="internet-optional" tabindex="-1">Internet: optional <a class="header-anchor" href="#internet-optional" aria-label="Permalink to &quot;Internet: optional&quot;">​</a></h3><p>Running the event needs no internet at all. These do, and only on the server unless noted:</p><ul><li><strong>Eventor</strong>: importing entries and uploading results;</li><li><strong>liveresultat</strong> and <strong>Cloud sync</strong>: publishing results online;</li><li><strong>Livelox</strong>: sending trackers&#39; positions;</li><li>The <strong>Street</strong>, <strong>Satellite</strong> and <strong>Topographic</strong> layers on <a href="./../running-the-event/live-view">Live view</a>, on the device showing them. Your own event map doesn&#39;t need it;</li><li><strong>Automatic updates</strong>.</li></ul><p>A phone hotspot shared with the server is enough for these. If the internet drops, they catch up when it comes back; the event carries on regardless.</p><h3 id="the-public-on-the-same-network" tabindex="-1">The public on the same network <a class="header-anchor" href="#the-public-on-the-same-network" aria-label="Permalink to &quot;The public on the same network&quot;">​</a></h3><p>If spectators can join the network, for example to see live results on their phones, set a <strong>PIN</strong> in <strong>Settings → Access protection</strong>. Then the manager screens and the registration desk ask for it, while results, the leaderboard and the spectator screens stay open. See <a href="./settings#access-protection">Settings</a>.</p><h2 id="the-server-computer" tabindex="-1">The server computer <a class="header-anchor" href="#the-server-computer" aria-label="Permalink to &quot;The server computer&quot;">​</a></h2><ul><li><strong>Pick a computer that stays put</strong> for the whole event, on mains power, with sleep switched off. Closing a laptop&#39;s lid usually sends it to sleep, and every other device loses the event until it wakes.</li><li><strong>Allow Manager through the firewall.</strong> On Windows, the first time Manager starts, Windows asks whether to let it communicate: tick <strong>Private networks</strong> and click <strong>Allow access</strong>. If you missed it, see <a href="./../download-and-install/#firewall-prompt-on-first-launch">Firewall prompt on first launch</a>. On a Mac, allow incoming connections for meshO Manager if asked.</li><li><strong>Check the venue network is a private one</strong> on Windows. A network marked <strong>Public</strong> blocks other devices even when Manager is allowed.</li><li><strong>Settings → Server → Allow access from other devices on the network</strong> must be on. It is to begin with.</li></ul><p>Manager listens on port <strong>5154</strong> unless you&#39;ve changed it in <strong>Settings → Server</strong>.</p><h2 id="which-address-each-device-uses" tabindex="-1">Which address each device uses <a class="header-anchor" href="#which-address-each-device-uses" aria-label="Permalink to &quot;Which address each device uses&quot;">​</a></h2><p><strong>Settings → Server</strong> lists each app&#39;s link twice: by the computer&#39;s <strong>name</strong> and by its <strong>IP</strong>. Which to use depends on the device:</p><ul><li><strong>Laptops doing the work</strong> (card download, station memory, the registration desk) should use the <strong>IP</strong> links. They need Chrome or Edge to read a SportIdent reader, and Chrome often can&#39;t find the computer by name.</li><li><strong>Phones, tablets and TVs</strong> should use the <strong>name</strong> links. They find the name on their own, and a name survives the server&#39;s IP changing.</li></ul><p>Each link has a <strong>QR code</strong> button, so a phone or tablet can open it with its camera. Full detail, including the exact Chrome error and how to give the server a name every browser can find: <a href="./server-addresses">Reaching the server: name or IP</a>.</p><h2 id="what-each-device-needs" tabindex="-1">What each device needs <a class="header-anchor" href="#what-each-device-needs" aria-label="Permalink to &quot;What each device needs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Device</th><th>What it opens</th><th>What it needs</th></tr></thead><tbody><tr><td><strong>The server</strong></td><td><code>http://localhost:5154/manager</code></td><td>Nothing else.</td></tr><tr><td><strong>Download laptop</strong></td><td>The <strong>Manager</strong> link, then <strong>Card downloads</strong></td><td>Chrome or Edge (or Firefox 151 or later), a SportIdent USB station, and <strong>HTTPS</strong> with meshO&#39;s certificate trusted, because a browser only lets a page use the reader over a secure link. See <a href="./https-and-certificates">HTTPS and certificates</a>. On a Mac, the CP210x driver too (<a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a>).</td></tr><tr><td><strong>Registration desk</strong></td><td>The <strong>Registration</strong> link</td><td>Any browser. To read card numbers off cards, the same as a download laptop. See <a href="./../running-the-event/late-entries#the-registration-desk">The registration desk</a>.</td></tr><tr><td><strong>Results and problems</strong></td><td>The <strong>Manager</strong> link</td><td>Any browser. A laptop is easier than a tablet for the detailed screens.</td></tr><tr><td><strong>Commentary</strong></td><td>The <strong>Commentary</strong> link</td><td>Any browser. See <a href="./../screens/commentary">Commentary</a>.</td></tr><tr><td><strong>TV screens</strong></td><td>A screen&#39;s own link, from the <strong>Screens</strong> page</td><td>A smart TV&#39;s browser, a media stick, or a computer driving one or more TVs. See <a href="./../screens/tv-screens">TV screens</a>.</td></tr><tr><td><strong>Info displays</strong> (start clock, radio control, pending downloads)</td><td>The <strong>Info</strong> link</td><td>A tablet or a small screen. See <a href="./../screens/info-screens">Event info screens</a>.</td></tr><tr><td><strong>Spectators&#39; phones</strong></td><td>The <strong>Spectator</strong> link, or its QR code</td><td>Any browser.</td></tr><tr><td><strong>Kiosk</strong> (a self-serve results lookup for competitors)</td><td>The <strong>Kiosk</strong> link</td><td>A tablet or a laptop.</td></tr></tbody></table><p>Every link opens with nothing to install and nothing to log into, apart from the PIN if you&#39;ve set one. Bookmark the link on each device, or add it to a phone&#39;s or tablet&#39;s home screen, so a volunteer can reopen it with one tap.</p><p><strong>Name each computer</strong> when Manager asks (&quot;Download A&quot;, &quot;Entry desk&quot;). The name says which computer made each change in the <a href="./audit-trail#naming-a-computer">audit trail</a>, and is how you pick out that computer when choosing where its splits print.</p><h3 id="printers" tabindex="-1">Printers <a class="header-anchor" href="#printers" aria-label="Permalink to &quot;Printers&quot;">​</a></h3><p>A printer can be on the network, on the server computer, or plugged into a download laptop by USB, and each computer&#39;s splits and labels go to the printer you choose for it. See <a href="./../running-the-event/splits-printing#choosing-your-setup">Printing splits</a>.</p><h2 id="splitting-the-work" tabindex="-1">Splitting the work <a class="header-anchor" href="#splitting-the-work" aria-label="Permalink to &quot;Splitting the work&quot;">​</a></h2><p>A common split for a mid-sized event:</p><table tabindex="0"><thead><tr><th>Who</th><th>Device</th><th>Doing</th></tr></thead><tbody><tr><td>Download desk (one or more)</td><td>Laptops with readers</td><td>Downloading cards, dealing with the obvious problems on the spot</td></tr><tr><td>Registration desk</td><td>Laptop or tablet</td><td>Late entries, card changes, hire cards</td></tr><tr><td>Results</td><td>The server, or a laptop</td><td>Watching the <a href="./../running-the-event/dashboard">dashboard</a>, resolving the problems, publishing results</td></tr><tr><td>Commentator</td><td>Laptop or tablet</td><td>Commentary and the leaderboard</td></tr><tr><td>Start</td><td>Tablet</td><td>The start clock and who is due</td></tr></tbody></table><p>Several download laptops can download at the same time. Each is its own desk with its own reader, and a card can be read at any of them.</p><h2 id="two-people-one-competitor" tabindex="-1">Two people, one competitor <a class="header-anchor" href="#two-people-one-competitor" aria-label="Permalink to &quot;Two people, one competitor&quot;">​</a></h2><p>Everyone works on the same event, so two people can change the same thing:</p><ul><li><strong>A change appears everywhere at once.</strong> A competitor&#39;s <strong>Edit competitor</strong> dialog, open on another laptop, shows the change as soon as it&#39;s saved, unless that laptop has an edit of its own still being saved.</li><li><strong>If both change the same competitor at the same moment, the later save stands.</strong> There&#39;s no merging and no warning. It&#39;s rare, because each save takes a fraction of a second, but agree who deals with what: the download desk fixes what it can on the spot, and everything else goes to one person.</li><li><strong>The audit trail keeps both.</strong> Every change is recorded with the computer that made it, so you can see what happened and put it right. See <a href="./audit-trail">Audit trail</a>.</li></ul><h2 id="when-a-device-loses-the-network" tabindex="-1">When a device loses the network <a class="header-anchor" href="#when-a-device-loses-the-network" aria-label="Permalink to &quot;When a device loses the network&quot;">​</a></h2><ul><li><strong>The device shows a banner</strong>, <em>Server unavailable — reconnecting…</em>, and keeps trying by itself. When it&#39;s back, everything on screen catches up with whatever changed in the meantime. There&#39;s no need to reload.</li><li><strong>A download laptop can&#39;t save cards while it&#39;s off the network.</strong> A card read then gets no confirming beep and shows an error. Read it again once the banner has gone. The control units&#39; memories still have the punches if something is ever missed (see <a href="./../running-the-event/station-memory">Station memory</a>).</li><li><strong>TV screens and info displays</strong> show that the connection was lost and reconnect by themselves. Nobody needs to stand at them.</li><li><strong>Don&#39;t reload a download laptop&#39;s page</strong> to fix it: that drops the reader, and you&#39;ll have to connect it again. See <a href="./../running-the-event/card-download">Card download</a>.</li></ul><p>If <strong>the server</strong> stops, every device shows the banner until it&#39;s running again, and then carries on. Nothing already saved is lost.</p><h2 id="how-many-devices" tabindex="-1">How many devices <a class="header-anchor" href="#how-many-devices" aria-label="Permalink to &quot;How many devices&quot;">​</a></h2><p>Manager sets no limit on how many devices connect. What limits it is the server computer and the network: put the server on a cable, keep other programs on it closed, and if the Wi-Fi is struggling, move the fixed desks onto cables before you cut down the screens.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">How meshO Manager works</a></li><li><a href="./server-addresses">Reaching the server: name or IP</a></li><li><a href="./https-and-certificates">HTTPS and certificates</a></li><li><a href="./../download-and-install/">Download, install and update</a></li><li><a href="./../running-the-event/splits-printing">Printing splits</a></li><li><a href="./../screens/tv-screens">TV screens</a></li><li><a href="./../screens/info-screens">Event info screens</a></li><li><a href="./audit-trail">Audit trail</a></li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li><li><a href="./settings">Settings</a></li></ul>',42)])])}const u=t(a,[["render",s]]);export{p as __pageData,u as default};
